-- 단기렌트 1일 요금 기준 기간별 할인 (2026-11-17)
--   1~3일 = 1일 요금 · 4~5일 95% · 6일 90% · 7일 이상 85% (1일 요금, 천원 단위 반올림) × 대여 일수
--   요금표(rate_table)에 1~30일 총액으로 넣음 (30일 넘으면 마지막 칸 1일 평균으로 계산)
--   7일 · 30일은 주단위렌트 · 월렌트 확정가가 우선 / 4구간 칸(day_rate 등)도 같은 1일 요금으로 맞춤
--   주행거리: 단기는 1일 400km × 대여 일수 (초과 1km당 요금은 주 · 월과 같음)
ALTER TABLE short_models ADD COLUMN day_km INTEGER NOT NULL DEFAULT 0;
UPDATE short_models SET day_km = 400;
UPDATE short_models SET day_rate = 60000, rate_3_4 = 57000, rate_5_6 = 54000, rate_7 = 51000, rate_table = '60000,120000,180000,228000,285000,324000,357000,408000,459000,510000,561000,612000,663000,714000,765000,816000,867000,918000,969000,1020000,1071000,1122000,1173000,1224000,1275000,1326000,1377000,1428000,1479000,1530000' WHERE name = '레이';
